# Build Supplementary Table 1 from repo output source tables.
#
# This is the public/reviewer-facing version of the working script archived at:
#   provenance/archived_scripts/supp_table1.R
#
# It does not rely on R objects left in the current session after meta_update.R.
# Instead, it reads source CSV/TSV files generated by the modular scripts in this
# repository and builds one Excel workbook plus matched source CSVs.
#
# Notes:
# - The original workbook was built after meta_update.R; metadata columns were
#   manually reviewed to remove/censor PHI before sharing.
# - This script includes a PHI-oriented metadata allowlist and writes only compact
#   source tables to the workbook. Full large DE tables remain as CSV source files.

suppressPackageStartupMessages({
  library(dplyr)
  library(tidyr)
  library(tibble)
  library(readr)
  library(stringr)
  library(purrr)
  library(openxlsx)
})

# ------------------------------------------------------------
# Paths
# ------------------------------------------------------------

repo_root <- normalizePath(getwd(), mustWork = FALSE)
if (!file.exists(file.path(repo_root, "README.md")) || !dir.exists(file.path(repo_root, "scripts"))) {
  stop("Run this script from the repository root, e.g. source('scripts/11_build_supplementary_table1.R').")
}

supp_dir <- file.path(repo_root, "outputs", "tables", "supplementary_table1")
csv_dir  <- file.path(supp_dir, "csv_source_tables")
dir.create(supp_dir, showWarnings = FALSE, recursive = TRUE)
dir.create(csv_dir, showWarnings = FALSE, recursive = TRUE)

xlsx_out <- file.path(supp_dir, "Supplementary_Table_1_MNP_spatial_analysis_outputs.xlsx")

# ------------------------------------------------------------
# Helpers
# ------------------------------------------------------------

as_chr_df <- function(x) {
  x %>%
    as_tibble() %>%
    mutate(across(everything(), ~ {
      if (inherits(.x, "Date") || inherits(.x, "POSIXct") || inherits(.x, "POSIXt")) {
        as.character(.x)
      } else if (is.factor(.x)) {
        as.character(.x)
      } else if (is.list(.x)) {
        vapply(.x, function(z) paste(z, collapse = "; "), character(1))
      } else {
        as.character(.x)
      }
    }))
}

placeholder_table <- function(table_id, description, source_figure, source, note) {
  tibble(
    table_id = table_id,
    description = description,
    source_figure = source_figure,
    source = source,
    note = note
  )
}

annotate_table <- function(x, table_id, description, source_figure = NA_character_, source = NA_character_) {
  if (is.null(x) || !is.data.frame(x)) {
    return(placeholder_table(table_id, description, source_figure, source, "TABLE NOT FOUND"))
  }
  as_chr_df(x) %>%
    mutate(
      table_id = table_id,
      description = description,
      source_figure = source_figure,
      source = source,
      .before = 1
    )
}

safe_read <- function(rel_path, table_id, description, source_figure = NA_character_) {
  path <- file.path(repo_root, rel_path)
  if (!file.exists(path)) {
    return(placeholder_table(table_id, description, source_figure, rel_path, "FILE NOT FOUND"))
  }
  ext <- tolower(tools::file_ext(path))
  x <- if (ext %in% c("tsv", "txt")) {
    readr::read_tsv(path, show_col_types = FALSE)
  } else {
    readr::read_csv(path, show_col_types = FALSE)
  }
  annotate_table(x, table_id, description, source_figure, rel_path)
}

safe_write_csv <- function(x, filename) {
  out <- file.path(csv_dir, filename)
  readr::write_csv(x, out)
  invisible(out)
}

write_sheet <- function(wb, sheet_name, df) {
  openxlsx::addWorksheet(wb, sheet_name)
  openxlsx::writeData(wb, sheet_name, df)
  openxlsx::freezePane(wb, sheet_name, firstRow = TRUE)
  if (nrow(df) > 0 && ncol(df) > 0) {
    openxlsx::addFilter(wb, sheet_name, row = 1, cols = seq_len(ncol(df)))
  }
  widths <- rep(14, ncol(df))
  names(widths) <- colnames(df)
  wide_cols <- c("description", "source", "source_file", "pathway", "term", "Description", "gene", "ligand", "target", "note")
  widths[colnames(df) %in% wide_cols] <- 30
  openxlsx::setColWidths(wb, sheet_name, cols = seq_len(ncol(df)), widths = pmin(widths, 42))
}

# Metadata allowlist: intentionally conservative. Avoids DOB, delivery/admission dates,
# MRNs, exact addresses, raw free-text clinical notes, and other direct identifiers.
metadata_allowlist <- c(
  "sample_id_standardized", "sample_id_std", "study_id", "donor_id", "pregnancy_id",
  "platform", "platform_clean", "platform_detail", "assay", "run_id",
  "Delivery_class", "MNPBurden", "MNPBurden_Delivery_class", "mnp_model_sample",
  "cumulative_mnp_ug_per_g", "cumulative_mnp_log10ugpg", "MNPBurden_threshold",
  "pe_ug_per_g", "pp_ug_per_g", "ps_ug_per_g", "pet_ug_per_g", "pmma_ug_per_g",
  "pvc_ug_per_g", "pu_ug_per_g", "pc_ug_per_g", "abs_ug_per_g", "sbr_ug_per_g",
  "n6_ug_per_g", "n66_ug_per_g",
  "gestational_age_weeks", "gestational_age_weeks_continuous", "birth_weight_g",
  "maternal_age_years", "maternal_bmi", "SDI_score", "SVI_score",
  "Prior_PTB", "Prior_PTB_TRUE", "Hypertension_TRUE", "Twins_TRUE",
  "Ethnicity_Race", "hospital", "histology_available", "MassivePVF", "Microcalc"
)

compact_if_metadata <- function(x) {
  if (is.null(x) || !is.data.frame(x)) return(x)
  keep <- intersect(metadata_allowlist, colnames(x))
  if (!length(keep)) return(x)
  x %>% select(all_of(keep))
}

