# Full DE can be large; keep full CSV in source tables, but include compact rows in Excel.
st1e_de_full_rel <- "outputs/tables/pseudobulk_de/Fig3_pseudobulk_DE_ALL_delivery.tsv"
st1e_de_full_path <- file.path(repo_root, st1e_de_full_rel)
st1e_de_compact <- if (file.exists(st1e_de_full_path)) {
  de_full <- readr::read_tsv(st1e_de_full_path, show_col_types = FALSE)
  readr::write_csv(de_full, file.path(csv_dir, "ST1e_full_subject_aware_limma_DE.csv"))
  de_full <- de_full %>% as_tibble()
  rank_col <- if ("adj.P.Val" %in% colnames(de_full)) "adj.P.Val" else if ("P.Value" %in% colnames(de_full)) "P.Value" else NA_character_
  de_full %>%
    mutate(
      abs_logFC = suppressWarnings(abs(as.numeric(logFC))),
      sig_rank = if (!is.na(rank_col)) suppressWarnings(as.numeric(.data[[rank_col]])) else NA_real_
    ) %>%
    group_by(across(any_of(c("Delivery_class", "predicted.celltype")))) %>%
    arrange(sig_rank, desc(abs_logFC), .by_group = TRUE) %>%
    slice_head(n = 250) %>%
    ungroup() %>%
    annotate_table(
      "ST1e.2",
      "Top subject-aware limma pseudobulk DE results by delivery class and predicted cell type; full table exported as ST1e_full_subject_aware_limma_DE.csv.",
      "Fig. 3a-c",
      "outputs/tables/pseudobulk_de/Fig3_pseudobulk_DE_ALL_delivery.tsv"
    )
} else {
  placeholder_table("ST1e.2", "Subject-aware limma pseudobulk DE results.", "Fig. 3a-c", st1e_de_full_rel, "FILE NOT FOUND")
}

