# ------------------------------------------------------------
# QC / missing table report
# ------------------------------------------------------------

all_tables <- list(
  st1a = st1a, st1b = st1b, st1c = st1c, st1d = st1d, st1e = st1e,
  st1f = st1f, st1g = st1g, st1h = st1h, st1i = st1i
)

qc <- purrr::imap_dfr(all_tables, function(x, nm) {
  tibble(
    table_group = nm,
    n_rows = nrow(x),
    n_cols = ncol(x),
    table_ids = paste(unique(x$table_id), collapse = "; ")
  )
})
readr::write_csv(qc, file.path(csv_dir, "ST1_source_table_QC_summary.csv"))

missing_report <- bind_rows(st1a, st1b, st1c, st1d, st1e, st1f, st1g, st1h) %>%
  filter(str_detect(coalesce(note, ""), "NOT FOUND|TABLE NOT FOUND|not a data"))
readr::write_csv(missing_report, file.path(csv_dir, "missing_or_placeholder_tables_report.csv"))

